"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def slidingWindowMax(arr, k):
    result = []
    deque = []
    for i in range(0, len(arr)):
        # Remove elements out of window from front
        while ((not (len(deque) == 0)) and (deque[0] <= (i - k))):
            deque.pop(0)
            # Maintain decreasing order in deque
        while ((not (len(deque) == 0)) and (arr[deque[-1]] <= arr[i])):
            deque.pop(-1)
        deque.append(i)
        # Add max to result once window is full
        if (i >= (k - 1)):
            result.append(arr[deque[0]])
    return result
